    static final List<Object> chains=new ArrayList<>();static int observationStart;
    @BeforeAll static void start()throws Exception{initialize();enableCrossHostTransport();}
    @AfterAll static void end()throws Exception{try{if(run!=null)Files.writeString(run.resolve("evidence/cross-host-"+testId+".json"),write(map("identity","Synthetic Code gateway; real binding, native Member/Clerk, grants, SessionService and deployed authorization","tls","Owned CA with normal hostname verification; no trust bypass","chains",chains,"requests",observations)),StandardOpenOption.CREATE_NEW);}finally{crossHostHttp=false;crossHostClient=null;deployedHttp=false;finish();}}
    @BeforeEach void before()throws Exception{new Stage1SupplyMatrixTest().refresh();observationStart=observations.size();}
    @AfterEach void after(TestInfo test){var requests=new ArrayList<>(observations.subList(observationStart,observations.size()));chains.add(map("method",test.getTestMethod().orElseThrow().getName(),"hostRequests",requests.stream().filter(r->object(r).has("host")).count(),"evidence",requests));}

    @Test void c01RejectedAdmissionResubmitsAndSameStoreBecomesBasicThenMockOnly()throws Exception{
        String open="cross_admission_"+req();var applicant=login(open);var draft=call(post(Stage1Routes.APPLICANT+"/application"),applicant.session(),map("requestId",req(),"payload",map("storeName","S1_TEST跨端草稿")),200);String id=draft.get("id").getAsString();
        var reentered=login(open);var restored=call(get(Stage1Routes.APPLICANT+"/application"),reentered.session(),null,200);assertEquals(id,restored.get("id").getAsString());assertTrue(restored.toString().contains("S1_TEST跨端草稿"));
        Object material=payload(upload(reentered.session(),Stage1Routes.APPLICANT));draft=call(put(Stage1Routes.APPLICANT+"/application/"+id+"/draft"),reentered.session(),map("requestId",req(),"expectedVersion",0,"payload",material),200);var submitted=call(post(Stage1Routes.APPLICANT+"/application/"+id+"/submit"),reentered.session(),map("requestId",req(),"expectedVersion",1),200);String store=submitted.get("storeId").getAsString();
        call(get(Stage1Routes.STORE+"/goods"),reentered.session(),null,403);call(post(Stage1Routes.MANAGER+"/applications/"+id+"/reject"),reviewer,map("requestId",req(),"expectedVersion",2,"revision",1,"reason","S1_TEST缺页请补正"),200);
        draft=call(put(Stage1Routes.APPLICANT+"/application/"+id+"/draft"),reentered.session(),map("requestId",req(),"expectedVersion",3,"payload",material),200);submitted=call(post(Stage1Routes.APPLICANT+"/application/"+id+"/submit"),reentered.session(),map("requestId",req(),"expectedVersion",4),200);assertEquals(2,submitted.get("revision").getAsInt());assertEquals(store,submitted.get("storeId").getAsString());
        call(post(Stage1Routes.MANAGER+"/applications/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",5,"revision",2),200);assertEquals(1,db.count("SELECT COUNT(*) FROM li_clerk WHERE store_id=? AND shopkeeper=1",store));assertEquals(1,db.count("SELECT COUNT(*) FROM li_store WHERE member_id=?",applicant.memberId()));assertEquals("REJECTED",db.required("SELECT status FROM li_p0_application_revision WHERE application_id=? AND revision=1",id).get("status"));
        call(post(cn.lili.common.security.session.http.SessionRoutes.refresh(SessionDomain.APPLICANT)),null,map("refreshToken",reentered.session().refreshToken()),403);var owner=new OwnerFixture(open,store,login(open));
        String agreement=agreementFixture(owner,0,LocalDate.now(Stage1Rules.ZONE),null);assertTrue(eligibility(owner).get("BASIC_ELIGIBLE").getAsBoolean());assertFalse(eligibility(owner).get("MOCK_READY").getAsBoolean());ruleFixture(owner,agreement,0);makeChannelReady(owner);
        var merchant=eligibility(owner);var manager=call(get(Stage1Routes.MANAGER+"/stores/"+store+"/eligibility").param("categoryId",category),operator,null,200);assertEquals(merchant.get("sourceFingerprint"),manager.get("sourceFingerprint"));assertTrue(merchant.get("MOCK_READY").getAsBoolean());assertFalse(merchant.get("REAL_READY").getAsBoolean());assertTrue(merchant.toString().contains("CHANNEL_PENDING"));
    }
