    @Test void c07EveryFulfillmentMethodHasPositivePrecheckAndIntersectionIsStrict()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();String pickup=createPointFixture(owner,"COMMUNITY_PICKUP"),redemption=createPointFixture(owner,"STORE_REDEMPTION");for(String point:List.of(pickup,redemption))call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST四方式"),200);
        var methods=object(deliveryMethods());methods.getAsJsonObject("MERCHANT_DELIVERY").addProperty("feeCent",300);methods.add("EXPRESS",object(map("enabled",true,"feeCent",500,"nationwide",true)));methods.getAsJsonObject("COMMUNITY_PICKUP").addProperty("enabled",true);methods.getAsJsonObject("STORE_REDEMPTION").addProperty("enabled",true);call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"methods",methods,"reason","S1_TEST全部四方式"),200);
        var g1=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("MERCHANT_DELIVERY","COMMUNITY_PICKUP"),true);var g2=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("COMMUNITY_PICKUP"),true);var g3=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("EXPRESS"),true);var g4=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("STORE_REDEMPTION"),true);var buyer=resident();
        for(var option:List.of(new Object[]{g1,"MERCHANT_DELIVERY",null},new Object[]{g2,"COMMUNITY_PICKUP",pickup},new Object[]{g3,"EXPRESS",null},new Object[]{g4,"STORE_REDEMPTION",redemption})){var result=precheck(owner,buyer,sku((JsonObject)option[0]),(String)option[1],(String)option[2],true);assertEquals("PASS",result.get("status").getAsString());}
        var items=List.of(map("skuId",sku(g1),"quantity",1),map("skuId",sku(g2),"quantity",1));var command=map("storeId",owner.store(),"items",items,"method","COMMUNITY_PICKUP","pointId",pickup);assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).get("status").getAsString());command.put("items",List.of(map("skuId",sku(g1),"quantity",1),map("skuId",sku(g3),"quantity",1)));assertEquals("BLOCKED",call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200).get("status").getAsString());
        assertEquals("INPUT_REQUIRED",precheck(owner,buyer,sku(g1),"MERCHANT_DELIVERY",null,false).get("status").getAsString());assertEquals("INPUT_REQUIRED",precheck(owner,buyer,sku(g2),"COMMUNITY_PICKUP",null,false).get("status").getAsString());assertEquals("BLOCKED",precheck(owner,buyer,sku(g2),"COMMUNITY_PICKUP",redemption,true).get("status").getAsString());
        call(post(Stage1Routes.STORE+"/points/"+pickup+"/disable"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"reason","S1_TEST最后自提点"),200);assertEquals("PASS",precheck(owner,buyer,sku(g1),"MERCHANT_DELIVERY",null,true).get("status").getAsString());assertEquals("BLOCKED",precheck(owner,buyer,sku(g2),"COMMUNITY_PICKUP",pickup,true).get("status").getAsString());
        var manager=call(get(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/fulfillment"),reviewer,null,200);var merchant=call(get(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),null,200);assertEquals(manager.get("version"),merchant.get("version"));assertEquals(manager.get("effectiveMethods"),merchant.get("effectiveMethods"));
    }
