    @Test void c12RealPersistedGoodsAndRepeatedConsumerPrechecksCreateNoBusinessEffects()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var goods=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("MERCHANT_DELIVERY"),true);String id=goods.getAsJsonObject("goods").get("id").getAsString(),sku=sku(goods);var buyer=resident();var read=call(get(Stage1Routes.BUYER+"/goods/"+id),buyer,null,200);assertFalse(read.toString().contains("costCent"));assertEquals(1,db.count("SELECT COUNT(*) FROM li_goods WHERE id=? AND store_id=?",id,owner.store()));
        var before=Stage1SupplyMatrixTest.factCounts();long quantity=db.count("SELECT quantity FROM li_goods_sku WHERE id=?",sku),version=db.count("SELECT inventory_version FROM li_p0_sku_control WHERE sku_id=?",sku);for(int i=0;i<100;i++){var result=precheck(owner,buyer,sku,"MERCHANT_DELIVERY",null,true);assertEquals("PASS",result.get("status").getAsString());assertEquals("MOCK",result.get("mode").getAsString());assertFalse(result.toString().contains("costCent"));}
        for(int i=0;i<100;i++)assertEquals("INPUT_REQUIRED",precheck(owner,buyer,sku,"MERCHANT_DELIVERY",null,false).get("status").getAsString());assertEquals(before,Stage1SupplyMatrixTest.factCounts());assertEquals(quantity,db.count("SELECT quantity FROM li_goods_sku WHERE id=?",sku));assertEquals(version,db.count("SELECT inventory_version FROM li_p0_sku_control WHERE sku_id=?",sku));assertFalse(eligibility(owner).get("REAL_READY").getAsBoolean());
        observations.add(map("case","C12","goodsId",id,"skuId",sku,"passRepeats",100,"inputRepeats",100,"ninePersistentFactCountsUnchanged",true,"sqlAndRedisReadOnlyEvidence","Stage1SupplyMatrixTest.bnd013 and Stage1PersistenceTest read-only probe; separate isolated-real-DB run"));
    }
    static JsonObject eligibility(OwnerFixture owner)throws Exception{return call(get(Stage1Routes.STORE+"/eligibility").param("categoryId",category),owner.login().session(),null,200);}
    static void makeChannelReady(OwnerFixture owner)throws Exception{String config=channelConfigFixture(0),relation=channelRelationFixture(owner,config);var row=relationCommand(relation,1,"submit");for(int i=0;i<3;i++)row=relationCommand(relation,row.get("version").getAsLong(),"query");relationCommand(relation,row.get("version").getAsLong(),"enable");}
    static SessionTokens resident(){String code=req();codes.put(code,"cross_resident_"+req());return residentLogin.login(code).session();}
    static String sku(JsonObject goods){return goods.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString();}
    static JsonObject precheck(OwnerFixture owner,SessionTokens buyer,String sku,String method,String point,boolean address)throws Exception{var command=map("storeId",owner.store(),"items",List.of(map("skuId",sku,"quantity",1)),"method",method);if(point!=null)command.put("pointId",point);if(address&&Set.of("MERCHANT_DELIVERY","EXPRESS").contains(method))command.put("address",map("provinceCode","990000","cityCode","990100","districtCode","990101"));return call(post(Stage1Routes.BUYER+"/precheck"),buyer,command,200);}
